<template><div><header class="topbar"><div class="crumb">设置 / <b>系统</b></div><div class="top-actions"><div class="avatar">AS</div></div></header><div class="content"><div class="page-title"><div><h1>系统设置</h1><p>维护测试数据和运行状态。</p></div></div><div class="panel" style="padding:18px;max-width:720px"><h2 style="font-size:16px;margin:0 0 8px">清理测试数据</h2><p class="muted" style="font-size:13px">只匹配 `seed prompt` 测试题，不会删除正式 5 题。建议先 dry-run 预览。</p><div class="row" style="margin-top:12px"><button class="btn ghost" @click="cleanup(true)">Dry run</button><button class="btn danger" @click="cleanup(false)">确认清理</button></div><pre v-if="result" style="background:#f7f9fc;padding:12px;border-radius:10px;font-size:12px;overflow:auto">{{JSON.stringify(result,null,2)}}</pre><h2 style="font-size:16px;margin:22px 0 8px">清理非正式题</h2><p class="muted" style="font-size:13px">删除所有非 active 的测试/草稿题目，正式 5 题保留。先 dry-run 预览。</p><div class="row" style="margin-top:12px"><button class="btn ghost" @click="cleanupNonActive(true)">Dry run</button><button class="btn danger" @click="cleanupNonActive(false)">确认清理</button></div><pre v-if="nonActive" style="background:#f7f9fc;padding:12px;border-radius:10px;font-size:12px;overflow:auto">{{JSON.stringify(nonActive,null,2)}}</pre></div></div><div v-if="toast" class="toast">{{toast}}</div></div></template>
<script setup>import {ref} from 'vue';import {api} from '../api';const result=ref(null),nonActive=ref(null),toast=ref('');async function cleanup(dryRun){if(!dryRun&&!confirm('确认永久删除 seed 测试题？'))return;try{result.value=await api('/api/v1/admin/maintenance/cleanup-seed',{method:'POST',body:{dryRun,confirm:!dryRun}});toast.value=dryRun?'Dry run 完成':'清理完成'}catch(e){toast.value=e.message}}async function cleanupNonActive(dryRun){if(!dryRun&&!confirm('确认删除所有非 active 测试题？'))return;try{nonActive.value=await api('/api/v1/admin/maintenance/cleanup-non-active',{method:'POST',body:{dryRun,confirm:!dryRun}});toast.value=dryRun?'Dry run 完成':'清理完成'}catch(e){toast.value=e.message}}</script>
